const items = $input.all();

return items.map(item => {
  const result = item.json;

  return {
    json: {
      date_found: new Date().toISOString(),

      job_title: result.job_title || '',
      company: result.company || '',
      location: result.location || '',
      employment_type: result.employment_type || '',

      source: result.source || '',
      url: result.url || '',

      match_score: result.match_score ?? '',
      match_level: result.match_level || '',
      recommendation: result.recommendation || '',

      experience_match: result.experience_match || '',

      matched_skills: Array.isArray(result.matched_skills)
        ? result.matched_skills.join('; ')
        : '',

      missing_skills: Array.isArray(result.missing_skills)
        ? result.missing_skills.join('; ')
        : '',

      transferable_skills: Array.isArray(result.transferable_skills)
        ? result.transferable_skills.join('; ')
        : '',

      status: result.recommendation === 'Apply'
        ? 'New'
        : 'Reviewed',

      source_job_id: result.source_job_id || '',
      dedup_key: result.dedup_key || ''
    }
  };
});

const items = $input.all();

return items.map(item => {
  const job = item.json;

  return {
    json: {
      title: job.title || '',
      company: job.company || '',
      location: job.location || '',
      description: job.description || '',
      source_link: job.source_link || '',
      share_link: job.share_link || '',
      job_id: job.job_id || '',
      via: job.via || '',
      job_url: job.source_link || '',
      job_source: job.via || ''
    }
  };
