const items = $input.all();

return items.map(item => {
  const job = item.json;

  const normalize = (value) =>
    String(value || '')
      .toLowerCase()
      .trim()
      .replace(/\s+/g, ' ');

  // Extract Indeed job ID directly from URL
  let sourceJobId = '';

  const jobUrl = String(job.job_url || job.source_link || '');

  const indeedMatch = jobUrl.match(/[?&]jk=([^&#]+)/i);

  if (indeedMatch) {
    sourceJobId = indeedMatch[1];
  }

  // Fallback key if no source-specific job ID is available
  const fallbackKey = [
    normalize(job.job_source),
    normalize(job.title),
    normalize(job.company),
    normalize(job.location)
  ].join('|');

  const dedupKey = sourceJobId
    ? `${normalize(job.job_source)}|${sourceJobId}`
    : fallbackKey;

  return {
    json: {
      ...job,
      source_job_id: sourceJobId,
      dedup_key: dedupKey
    }
  };
});

const existingItems = $input.all();
const newItems = $('Create Job Dedup Key').all();

const normalize = (value) =>
  String(value ?? '')
    .trim()
    .toLowerCase();

const existingKeys = new Set();
const existingSourceIds = new Set();

for (const item of existingItems) {
  const key = normalize(item.json.dedup_key);
  const sourceId = normalize(item.json.source_job_id);

  if (key) {
    existingKeys.add(key);
  }

  if (sourceId) {
    existingSourceIds.add(sourceId);
  }
}

const newJobs = [];

for (const item of newItems) {
  const job = item.json;

  const dedupKey = normalize(job.dedup_key);
  const sourceJobId = normalize(job.source_job_id);

  const duplicateByKey =
    dedupKey && existingKeys.has(dedupKey);

  const duplicateBySourceId =
    sourceJobId && existingSourceIds.has(sourceJobId);

  if (duplicateByKey || duplicateBySourceId) {
    continue;
  }

  newJobs.push(item);
}

return newJobs;

const items = $input.all();
const jobs = $('Limit').all();

return items.map((item, index) => {
  const raw =
    item.json.text ??
    item.json.output ??
    item.json.response?.generations?.[0]?.[0]?.text ??
    '';

  if (!raw) {
    throw new Error(`AI returned empty text for item ${index}`);
  }

  const cleaned = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let result;

  try {
    result = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(`Invalid JSON for item ${index}:\n${cleaned}`);
  }

  // IMPORTANT:
  // Match AI result with the exact job entering the AI node
  const job = jobs[index]?.json || {};

  return {
    json: {
      ...result,

      job_title: job.job_title || job.title || '',
      company: job.company || '',
      location: job.location || '',
      employment_type: job.employment_type || '',

      source: job.source || job.job_source || '',
      url: job.url || job.job_url || job.source_link || '',

      source_job_id:
        job.source_job_id ||
        job.job_id ||
        '',

      dedup_key: job.dedup_key || ''
    }
  };
});

